contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay
    ) public payable {
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Grant PROPOSER_ROLE to msg.sender so the test contract can schedule and cancel.
        c.grantRole(c.PROPOSER_ROLE(), msg.sender);

        // Schedule the operation with a delay that meets the minimum.
        c.schedule(target, value, data, predecessor, salt, delay);

        // The operation must be pending immediately after scheduling.
        require(c.isOperation(id), "not scheduled");
        require(c.isOperationPending(id), "not pending after scheduling");

        // Cancel the operation.
        c.cancel(id);

        // General rule: cancellation removes the scheduled operation entirely.
        assert(
            !c.isOperation(id) &&
            !c.isOperationPending(id) &&
            !c.isOperationReady(id) &&
            !c.isOperationDone(id) &&
            c.getTimestamp(id) == 0
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay
    ) public payable {
        // Bound the delay tightly to keep the test within checker limits.
        require(delay >= c.getMinDelay() && delay <= c.getMinDelay() + 1000, "delay out of range");

        // Grant PROPOSER_ROLE to this test contract so it can schedule.
        c.grantRole(c.PROPOSER_ROLE(), msg.sender);

        // Schedule the operation.
        c.schedule(target, value, data, predecessor, salt, delay);

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        uint256 ts = c.getTimestamp(id);

        // The general rule: a successfully scheduled operation is pending and ready.
        assert(ts > block.timestamp && c.isOperation(id) && c.isOperationPending(id) && c.isOperationReady(id));
    }
}

